-- Day 15: user-supplied TEST 204.pdf + Archive.org audio (Volume 9 Test 8).
-- Q16 is B: school office payment, verified against the transcript, not the incorrect C in a secondary key.
-- Supplied PDF map retained. Existing learner results must never be removed.
insert into public.ark60_content(day_number,module,title,status,payload,published_at,updated_at)
values(15,'listening','IELTS Listening Test 204','published',$json${"version": "listening-test-204-v1", "test_code": "TEST-204", "audio_url": "https://ia601600.us.archive.org/6/items/test-204-ready/TEST_204_ready.mp3", "total_questions": 40, "audio_once": true, "sections": [{"number": 1, "label": "SECTION 1", "range": "Questions 1–10", "blocks": [{"kind": "notes", "range": "Questions 1–10", "instruction": "Complete the notes below.", "word_limit": "Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer.", "title": "Call Record Card", "items": [["Example: Caller’s phone number: 03786 439251"], ["Caller’s name: Robert ", {"q": 1}], ["Address: 27 ", {"q": 2}], ["Moortown"], ["Postcode: DP17 5HJ"], ["Date of birth: ", {"q": 3}, ", 1975"], ["Doctor’s name: Dr Craven"], ["Doctor’s address: Moortown Health Centre"], ["Reason for call: Pain in his ", {"q": 4}, " back"], ["Previous history: Similar back problem in June last year"], ["Details of present problem: Started ", {"q": 5}, " ago"], ["Got worse this ", {"q": 6}], ["No abdominal pain"], ["Possible cause: Lifting up a heavy ", {"q": 7}], ["Treatment already applied: Has applied heat"], ["Has taken ", {"q": 8}], ["Advice given: Try using ", {"q": 9}], ["Go to doctor tomorrow"], ["Ask for information about ", {"q": 10}]]}]}, {"number": 2, "label": "SECTION 2", "range": "Questions 11–20", "blocks": [{"kind": "mcq", "range": "Questions 11–16", "instruction": "Choose the correct answer, A, B or C.", "title": "Preparing for a trip to an outdoor education centre", "questions": [{"q": 11, "text": "A trip to the outdoor education centre will help the children", "options": {"A": "create good relationships", "B": "manage without adult supervision", "C": "react positively to new challenges"}}, {"q": 12, "text": "To prepare their children for the trip, parents should", "options": {"A": "let them try sleeping in a tent at home", "B": "make sure they get enough sleep before they leave", "C": "tell them that they will be in a tent with their friends"}}, {"q": 13, "text": "What do parents need to put in their children’s backpack?", "options": {"A": "plastic bags", "B": "snacks and biscuits", "C": "a small amount of money"}}, {"q": 14, "text": "What are children allowed to bring on the trip?", "options": {"A": "electronic games", "B": "cell phones", "C": "penknives"}}, {"q": 15, "text": "How are parents selected to attend the trip?", "options": {"A": "The first ten parents to sign up will be able to go", "B": "Parents’ names will be chosen from a box", "C": "Preference will be given to parents with camping skills"}}, {"q": 16, "text": "Payment for the trip", "options": {"A": "must be handed to the child’s teacher", "B": "can be left at the school office", "C": "should be made directly to the outdoor education centre"}}]}, {"kind": "matching", "range": "Questions 17–20", "instruction": "Label the map below. Choose the correct letter, A–G, next to questions 17–20.", "title": "Outdoor Education Centre", "image_url": "/listening/test-204-outdoor-education-centre-map.png", "image_alt": "Outdoor education centre map: entrance, reception, main hall, kitchen, river, bridges and locations A–G.", "hide_choices": true, "choices": {"A": "A", "B": "B", "C": "C", "D": "D", "E": "E", "F": "F", "G": "G"}, "items": [{"q": 17, "text": "Woodcarving studio"}, {"q": 18, "text": "Emergency meeting point"}, {"q": 19, "text": "Conservation centre"}, {"q": 20, "text": "Arts and crafts room"}]}]}, {"number": 3, "label": "SECTION 3", "range": "Questions 21–30", "blocks": [{"kind": "mcq", "range": "Questions 21–24", "instruction": "Choose the correct answer, A, B or C.", "title": "Stone Point: A New Zealand historical site", "questions": [{"q": 21, "text": "According to Liz, Stone Point played a key role in local history because", "options": {"A": "it was used for defence or attack purposes.", "B": "it was the landing point for the first Maori settlers.", "C": "it was developed as a commercial port."}}, {"q": 22, "text": "Scott and Liz agree Maori originally chose to inhabit Stone Point because of", "options": {"A": "its rich soil.", "B": "the supply of fish.", "C": "available building materials."}}, {"q": 23, "text": "Scott and Liz agree that using Maori terminology in their presentation", "options": {"A": "will be of interest to international students.", "B": "is required as a component of their research.", "C": "would be best avoided."}}, {"q": 24, "text": "When Scott mentions the engines at Stone Point, Liz advises him to", "options": {"A": "focus on the human aspect instead.", "B": "check the accuracy of specific dates.", "C": "explain complex technical language."}}]}, {"kind": "matching", "range": "Questions 25–30", "instruction": "What do Liz and Scott agree they must do for each of the following sections for their presentation on Stone Point? Choose SIX correct answers, A–H, next to questions 25–30.", "title": "Sections of Presentation — Things to do", "choices": {"A": "provide further description", "B": "find images", "C": "set up an interview", "D": "check author’s details", "E": "check the exact location", "F": "obtain official permission", "G": "be more objective", "H": "reduce it in length"}, "items": [{"q": 25, "text": "Early Maori inhabitation of Stone Point"}, {"q": 26, "text": "The use of Stone Point as a lookout point"}, {"q": 27, "text": "The reconstruction of the fort"}, {"q": 28, "text": "Modernisation of the fort in the 1930s–40s"}, {"q": 29, "text": "Uses of Stone Point from 1950s to the present day"}, {"q": 30, "text": "The use of Stone Point as a public park"}]}]}, {"number": 4, "label": "SECTION 4", "range": "Questions 31–40", "blocks": [{"kind": "notes_groups", "range": "Questions 31–40", "instruction": "Complete the notes below.", "word_limit": "Write NO MORE THAN TWO WORDS for each answer.", "title": "Rural Development — The Berbers", "groups": [{"heading": "The Berbers", "items": [["lived in various countries in North Africa"], ["were driven from their homes during the 12th century"], ["began to lead a nomadic life, moving across ", {"q": 31}, " and mountains"]]}, {"heading": "Different Berber Lifestyles", "items": [["some Berbers, known as ", {"q": 32}, " nomads, moved twice a year"], ["some Berbers were completely nomadic"], ["some Berbers settled by oases, producing fruit, vegetables, and ", {"q": 33}, " to cook with"], ["people and belongings were carried by ", {"q": 34}], ["settled Berbers lived in houses"], ["nomadic Berbers used tents"], ["settled communities organised themselves by holding regular meetings in the ", {"q": 35}, " of the village"]]}, {"heading": "The Tuaregs", "items": [["if goatskins were unavailable, tents were made from ", {"q": 36}, " or palm-leaf mats"], ["Tuareg labourers were the descendants of ", {"q": 37}], ["adult men always wore a ", {"q": 38}, " veil"], ["some Tuaregs moved to Burkina Faso with their ", {"q": 39}]]}, {"heading": "Tuaregs and Timbuktu", "items": [["Timbuktu was settled by Tuaregs around 1000 years ago"], ["the city built wealth on the salt and gold trades"], ["some Tuaregs now work as ", {"q": 40}, " for the Malian Department of Tourism"]]}]}]}], "answer_key": {"1": ["Ridyard"], "2": ["Station Road"], "3": ["25 February", "25th February", "February 25", "February 25th", "25 Feb", "25th Feb", "Feb 25", "Feb 25th"], "4": ["lower"], "5": ["three days", "3 days"], "6": ["afternoon"], "7": ["box"], "8": ["painkillers"], "9": ["ice"], "10": ["exercise"], "11": ["C"], "12": ["B"], "13": ["A"], "14": ["B"], "15": ["A"], "16": ["B"], "17": ["E"], "18": ["A"], "19": ["F"], "20": ["B"], "21": ["A"], "22": ["B"], "23": ["C"], "24": ["A"], "25": ["D"], "26": ["B"], "27": ["A"], "28": ["F"], "29": ["C"], "30": ["E"], "31": ["deserts"], "32": ["seasonal"], "33": ["olive oil"], "34": ["camels"], "35": ["square"], "36": ["grass"], "37": ["slaves"], "38": ["dark blue"], "39": ["herds"], "40": ["guides"]}}$json$::jsonb,now(),now())
on conflict(day_number,module) do update set title=excluded.title,status=excluded.status,payload=excluded.payload,published_at=coalesce(ark60_content.published_at,now()),updated_at=now()
where ark60_content.payload->>'test_code'='TEST-204';
